//! Colour-space value types.
//!
//! Every channel is an `f32`, exactly like the C++ originals (`float`), and the
//! constructors store what they are given: none of these types clamp or
//! normalise their inputs, so out-of-gamut values flow through untouched.

/// Red / green / blue, nominally in `0.0 ..= 1.0`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

/// Hue in degrees, saturation and lightness in `0.0 ..= 1.0`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

/// Hue in degrees, saturation and value in `0.0 ..= 1.0`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

/// Cyan / magenta / yellow / key.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

/// Luma plus the two colour-difference channels.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Self { r, g, b }
    }

    /// 8-bit channels scaled into the unit range, as `RGB::fromInt` does.
    pub fn from_int(r: i32, g: i32, b: i32) -> Self {
        Self {
            r: r as f32 / 255.0,
            g: g as f32 / 255.0,
            b: b as f32 / 255.0,
        }
    }
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Self { h, s, l }
    }
}

impl Hsv {
    pub fn new(h: f32, s: f32, v: f32) -> Self {
        Self { h, s, v }
    }
}

impl Cmyk {
    pub fn new(c: f32, m: f32, y: f32, k: f32) -> Self {
        Self { c, m, y, k }
    }
}

impl Yuv {
    pub fn new(y: f32, u: f32, v: f32) -> Self {
        Self { y, u, v }
    }
}

