//! `std::cout << float` reproduced exactly.
//!
//! An iostream inserted `float` is promoted to `double` and handed to the C
//! library as `%.*g` with the stream's default precision of 6. So the rules to
//! reproduce are printf's `%g` rules:
//!
//! * let `x` be the decimal exponent of the value *after* rounding to 6
//!   significant digits;
//! * if `x < -4` or `x >= 6`, use `%e` style with 5 fractional digits,
//!   otherwise `%f` style with `5 - x` fractional digits;
//! * strip trailing fractional zeros, then a bare trailing point;
//! * exponents always carry a sign and at least two digits.

/// Formats a `f32` the way `operator<<(std::ostream&, float)` would.
pub fn cout_float(v: f32) -> String {
    // The promotion to `double` is exact and is what the C++ stream does before
    // formatting, so the digits come from the wider type.
    format_g(v as f64, 6)
}

/// `printf("%.*g", precision, v)` for a `f64`.
pub fn format_g(v: f64, precision: usize) -> String {
    let sign = if v.is_sign_negative() { "-" } else { "" };

    if v.is_nan() {
        return format!("{sign}nan");
    }
    let magnitude = v.abs();
    if magnitude.is_infinite() {
        return format!("{sign}inf");
    }
    if magnitude == 0.0 {
        return format!("{sign}0");
    }

    // `%g` treats a precision of 0 as 1.
    let digits = precision.max(1);

    // Rounding to scientific notation first tells us which style to use: the
    // exponent has to be the one the *rounded* value has, so that a value like
    // 999999.5 is seen as 1e+06 and takes the exponential branch.
    let scientific = format!("{:.*e}", digits - 1, magnitude);
    let (mantissa, exponent) = scientific
        .split_once('e')
        .expect("Rust's LowerExp always emits an exponent");
    let exponent: i32 = exponent.parse().expect("exponent is a decimal integer");

    if exponent < -4 || exponent >= digits as i32 {
        let sign_char = if exponent < 0 { '-' } else { '+' };
        format!(
            "{sign}{}e{sign_char}{:02}",
            trim_trailing_zeros(mantissa),
            exponent.unsigned_abs()
        )
    } else {
        let fractional = (digits as i32 - 1 - exponent) as usize;
        let fixed = format!("{:.*}", fractional, magnitude);
        format!("{sign}{}", trim_trailing_zeros(&fixed))
    }
}

/// Drops trailing zeros from the fractional part, and the point if it is then
/// left dangling. Integral strings are returned untouched.
fn trim_trailing_zeros(s: &str) -> &str {
    match s.find('.') {
        None => s,
        Some(_) => s.trim_end_matches('0').trim_end_matches('.'),
    }
}

