//! optional `p` exponent, `inf`/`infinity`, or `nan` with an optional
//! parenthesised tag. Trailing junk is ignored, and a significand followed by a
//! bare `e`/`p` backtracks to the significand alone.

/// Why a `stof` call failed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// No conversion could be performed — `std::invalid_argument`.
    Invalid,
    /// The value overflowed or underflowed `float` — `std::out_of_range`.
    OutOfRange,
}

impl StofError {
    /// The exception type name, as libstdc++ prints it when one escapes `main`.
    pub fn exception_name(self) -> &'static str {
        match self {
            StofError::Invalid => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
