        while j < bytes.len() && bytes[j].is_ascii_digit() {
            significand_is_zero &= bytes[j] == b'0';
            digits += 1;
            j += 1;
        }
    }
    if digits == 0 {
        return Err(StofError::Invalid);
    }

    if let Some(end) = exponent_end(bytes, j, b'e') {
        j = end;
    }

    // Rust's float parser accepts every shape this scanner produces ("5.",
    // ".5", "+.5e-3", oversized exponents), so the matched slice — sign
    // included, trailing junk excluded — can go straight in.
    let start = if negative { after_sign - 1 } else { after_sign };
    let value = std::str::from_utf8(&bytes[start..j])
        .ok()
        .and_then(|slice| slice.parse::<f32>().ok())
        .ok_or(StofError::Invalid)?;

    range_check(value, significand_is_zero)
}

/// Rejects results that glibc would have flagged with `ERANGE`: infinities from
/// overflow, zeros from a nonzero significand, and subnormals.
fn range_check(value: f32, significand_is_zero: bool) -> Result<f32, StofError> {
    if value.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    if value == 0.0 {
        if significand_is_zero {
            return Ok(value);
        }
        return Err(StofError::OutOfRange);
    }
    if value.abs() < f32::MIN_POSITIVE {
        return Err(StofError::OutOfRange);
    }
    Ok(value)
}

/// End index of an `e`/`p` exponent starting at `at`, or `None` if there is no
/// complete exponent there (in which case the caller keeps the significand).
fn exponent_end(bytes: &[u8], at: usize, marker: u8) -> Option<usize> {
    let mut j = at;
    if j >= bytes.len() || (bytes[j] | 0x20) != marker {
        return None;
    }
    j += 1;
    if matches!(bytes.get(j), Some(b'+' | b'-')) {
        j += 1;
    }
    if !bytes.get(j).is_some_and(u8::is_ascii_digit) {
        return None;
    }
    while bytes.get(j).is_some_and(u8::is_ascii_digit) {
        j += 1;
    }
    Some(j)
}

/// Parses a hex significand (the text after `0x`) with an optional `p`
/// exponent. Returns the value and whether the significand was all zeros, or
/// `None` when there is no hex digit to consume.
fn parse_hex(bytes: &[u8], negative: bool) -> Option<(f32, bool)> {
    let mut i = 0;
    // Significand, kept in a u64 with a sticky bit for anything that overflows,
    // and a base-2 exponent that tracks the position of its low bit.
    let mut mantissa: u64 = 0;
    let mut sticky = false;
    let mut exponent: i32 = 0;
    let mut digits = 0;
    let mut seen_point = false;

    while i < bytes.len() {
        let byte = bytes[i];
        if byte == b'.' && !seen_point {
            seen_point = true;
            i += 1;
            continue;
        }
        let Some(nibble) = hex_value(byte) else { break };
        digits += 1;
        if mantissa >> 60 == 0 {
            mantissa = (mantissa << 4) | u64::from(nibble);
        } else {
            // No room left: the digit only contributes a sticky bit, and the
            // significand's low bit moves up four places.
            sticky |= nibble != 0;
            exponent += 4;
        }
        if seen_point {
            exponent -= 4;
        }
        i += 1;
    }
    if digits == 0 {
        return None;
    }

    if let Some(end) = exponent_end(bytes, i, b'p') {
        let text = std::str::from_utf8(&bytes[i + 1..end]).ok()?;
        let written: i64 = text.parse().unwrap_or(if text.starts_with('-') {
            i64::MIN
        } else {
            i64::MAX
        });
        exponent = (i64::from(exponent).saturating_add(written))
            .clamp(i32::MIN as i64 / 2, i32::MAX as i64 / 2) as i32;
    }

    Some(round_to_f32(negative, mantissa, sticky, exponent))
}

/// Nearest `f32` to `mantissa * 2^exponent`, ties to even. `sticky` marks
/// discarded nonzero bits below the mantissa's low bit.
fn round_to_f32(negative: bool, mantissa: u64, sticky: bool, exponent: i32) -> f32 {
    let sign = if negative { 1u32 << 31 } else { 0 };
    if mantissa == 0 {
        return f32::from_bits(sign);
    }

    // Quantum exponent of the result: 23 places below the leading bit, but never
    // below the smallest subnormal's.
    let leading = exponent + 63 - mantissa.leading_zeros() as i32;
    let quantum = (leading - 23).max(-149);

    let shift = quantum - exponent;
    let mut significand: u64;
    if shift <= 0 {
        significand = mantissa << (-shift) as u32;
    } else {
        let (kept, guard, rest) = if shift >= 64 {
            (0, if shift == 64 { mantissa >> 63 } else { 0 }, true)
        } else {
            let low_mask = (1u64 << (shift - 1)) - 1;
            (
                mantissa >> shift,
                (mantissa >> (shift - 1)) & 1,
                mantissa & low_mask != 0,
            )
        };
        significand = kept;
        if guard == 1 && (rest || sticky || significand & 1 == 1) {
            significand += 1;
        }
    }

    // Rounding up can carry into a 25th bit; renormalise.
    let mut quantum = quantum;
    if significand >> 24 != 0 {
        significand >>= 1;
        quantum += 1;
    }

    if significand == 0 {
        return f32::from_bits(sign);
    }
    if significand >> 23 == 0 {
        // Subnormal: the quantum is pinned at 2^-149 and the significand is the
        // fraction field outright.
        return f32::from_bits(sign | significand as u32);
    }
    let exponent_field = quantum + 150;
    if exponent_field >= 255 {
        return f32::from_bits(sign | 0x7f80_0000);
    }
    f32::from_bits(sign | ((exponent_field as u32) << 23) | (significand as u32 & 0x7f_ffff))
}

fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn matches_ignore_case(bytes: &[u8], prefix: &[u8]) -> bool {
    bytes.len() >= prefix.len()
        && bytes
            .iter()
            .zip(prefix)
            .all(|(byte, want)| byte | 0x20 == *want)
}

