//! Port of `tests/test12.cpp`: convert one RGB triple into HSL, HSV, CMYK and
//! YUV, and print all thirteen components on a single line.
//!
//! Usage: `test12 [r g b]` — all three channels must be supplied together, or
//! the built-in default colour is used.

#[path = "src/color/mod.rs"]
mod color;

use color::{cout_float, rgb_to_cmyk, rgb_to_hsl, rgb_to_hsv, rgb_to_yuv, stof, Rgb};

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r = 0.4f32;
    let mut g = 0.2f32;
    let mut b = 0.8f32;

    if args.len() > 3 {
        r = parse_channel(&args[1]);
        g = parse_channel(&args[2]);
        b = parse_channel(&args[3]);
    }

    let rgb = Rgb::new(r, g, b);

    let hsl = rgb_to_hsl(&rgb);
    let hsv = rgb_to_hsv(&rgb);
    let cmyk = rgb_to_cmyk(&rgb);
    let yuv = rgb_to_yuv(&rgb);

    println!(
        "{} {} {} {} {} {} {} {} {} {} {} {} {}",
        cout_float(hsl.h),
        cout_float(hsl.s),
        cout_float(hsl.l),
        cout_float(hsv.h),
        cout_float(hsv.s),
        cout_float(hsv.v),
        cout_float(cmyk.c),
        cout_float(cmyk.m),
        cout_float(cmyk.y),
        cout_float(cmyk.k),
        cout_float(yuv.y),
        cout_float(yuv.u),
        cout_float(yuv.v),
    );
}

/// The C++ driver calls `std::stof` without a try block, so a bad argument lets
/// the exception escape `main`: libstdc++ reports it on stderr and aborts.
fn parse_channel(text: &str) -> f32 {
    match stof(text) {
        Ok(value) => value,
        Err(error) => {
            eprintln!(
                "terminate called after throwing an instance of '{}'",
                error.exception_name()
            );
            eprintln!("  what():  stof");
            std::process::abort();
        }
    }
}

