use std::process::Command;

// xorshift64* — deterministic, so a failing run can be replayed.
struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
    fn unit(&mut self) -> f64 {
        (self.next() >> 11) as f64 / (1u64 << 53) as f64
    }
}

/// A grab bag of textual channel values, weighted toward the shapes that stress
/// the converters: exact boundaries, ties, denormal-ish magnitudes, junk.
fn channel(rng: &mut Rng) -> String {
    match rng.below(20) {
        0 => ["0", "1", "0.5", "-0", "+0", "0.0", "1.0", "-1", "2", "255"][rng.below(10) as usize]
            .to_string(),
        1 => format!("{}", rng.below(256) as f64 / 255.0),
        2 => format!("{:e}", (rng.unit() - 0.5) * 1e10),
        3 => format!("{:e}", rng.unit() * 1e-37),
        4 => format!("{:e}", rng.unit() * 3.4e38),
        5 => format!("{}", (rng.unit() * 4.0) - 2.0),
        6 => ["inf", "-inf", "nan", "-nan", "INFINITY", "NaN"][rng.below(6) as usize].to_string(),
        7 => ["0x1p-3", "0x10", "0xabc.dep2", "0x.8", "1e", "5.", ".5", "1e-40", "9e99", "abc", ""]
            [rng.below(11) as usize]
            .to_string(),
        8 => format!("{:.*}", rng.below(9) as usize, rng.unit()),
        9 => format!("{}", 1.0 / (1 + rng.below(64)) as f64),
        _ => format!("{}", rng.unit()),
    }
}

fn run(program: &str, args: &[String]) -> (String, String, Option<i32>) {
    let out = Command::new(program).args(args).output().expect("spawn");
    (
        String::from_utf8_lossy(&out.stdout).into_owned(),
        String::from_utf8_lossy(&out.stderr).into_owned(),
        out.status.code(),
    )
}

fn main() {
    let mut argv = std::env::args().skip(1);
    let cpp = argv.next().unwrap();
    let rs = argv.next().unwrap();
    let iterations: u64 = argv.next().unwrap().parse().unwrap();
    let mut rng = Rng(0x9e37_79b9_7f4a_7c15);

    let mut mismatches = 0u64;
    for i in 0..iterations {
        // Occasionally vary the argument count to exercise the `argc > 3` gate.
        let count = match rng.below(40) {
            0 => rng.below(4),
            _ => 3 + rng.below(2),
        };
