/// `addss`: the sum, except that when *both* operands are NaN the left-hand one
/// is the result.
///
/// The C++ build accumulates these sums left to right with the running total in
/// the destination register, and x86 returns the destination's NaN in that case
/// — so the leftmost NaN channel decides the sign that gets printed. Rust makes
/// no promise about which operand LLVM parks in the destination, hence the
/// explicit preference. (Subtraction and division need no such help: they are
/// not commutative, so their operand order is already fixed.)
#[inline]
fn add(lhs: f32, rhs: f32) -> f32 {
    if lhs.is_nan() {
        lhs
    } else {
        lhs + rhs
    }
}

/// `subss`, written in the same shape as [`add`] to keep the sums below
/// readable.
#[inline]
fn sub(lhs: f32, rhs: f32) -> f32 {
    if lhs.is_nan() {
        lhs
    } else {
        lhs - rhs
    }
}

/// `ColorConverter::rgbToYUV`, using the BT.601 coefficients.
pub fn rgb_to_yuv(c: &Rgb) -> Yuv {
    let (r, g, b) = (c.r, c.g, c.b);
    Yuv::new(
        add(add(0.299 * r, 0.587 * g), 0.114 * b),
        add(sub(-0.147 * r, 0.289 * g), 0.436 * b),
        sub(sub(0.615 * r, 0.515 * g), 0.100 * b),
    )
}

