//! RGB → HSL / HSV / CMYK / YUV conversions.
//!
//! Precision notes — the C++ original works entirely in `float`, so every
//! intermediate here is `f32` too, and the operations are kept in the same
//! order and the same groupings. That matters: `h / 6.0 * 360.0` and `h * 60.0`
//! are algebraically equal but not bit-equal, and `delta / (max + min)` differs
//! in the last bits from `delta / (1.0 - (2.0 * l - 1.0).abs())`. Out-of-range
//! inputs are never clamped, so negative saturations and lightnesses > 1 are
//! reproduced faithfully.

use super::types::{Cmyk, Hsl, Hsv, Rgb, Yuv};

/// `std::max<float>(a, b)`, which returns `a < b ? b : a`.
///
/// The tie/NaN behaviour is load-bearing: `max(-0.0, 0.0)` yields `-0.0`, and a
/// NaN in `a` is passed through because every comparison against it is false.
#[inline]
fn max_f(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// `std::min<float>(a, b)`, which returns `b < a ? b : a`.
#[inline]
fn min_f(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

/// The channel extremes, as `max(max(r, g), b)` / `min(min(r, g), b)`.
#[inline]
fn extremes(c: &Rgb) -> (f32, f32) {
    (
        max_f(max_f(c.r, c.g), c.b),
        min_f(min_f(c.r, c.g), c.b),
    )
}

/// Hue in degrees, shared verbatim by the HSL and HSV conversions.
///
/// The sector is picked by comparing each channel against `max`; the red sector
/// folds a negative hue up by adding a whole turn (six sixths) before the final
/// scaling, rather than adding 360 afterwards.
fn hue_degrees(c: &Rgb, max: f32, delta: f32) -> f32 {
    let mut h = if c.r == max {
        (c.g - c.b) / delta + if c.b > c.g { 6.0 } else { 0.0 }
    } else if c.g == max {
        2.0 + (c.b - c.r) / delta
    } else {
        4.0 + (c.r - c.g) / delta
    };
    h /= 6.0;
    h *= 360.0;
    h
}

/// `ColorConverter::rgbToHSL`.
pub fn rgb_to_hsl(c: &Rgb) -> Hsl {
    let (max, min) = extremes(c);
    let l = (max + min) / 2.0;

    let (h, s);
    if max == min {
        s = 0.0;
        h = s;
    } else {
        let delta = max - min;
        s = if l > 0.5 {
            delta / (2.0 - max - min)
        } else {
            delta / (max + min)
        };
        h = hue_degrees(c, max, delta);
    }

    Hsl::new(h, s, l)
}

/// `ColorConverter::rgbToHSV`.
pub fn rgb_to_hsv(c: &Rgb) -> Hsv {
    let (max, min) = extremes(c);
    let v = max;
    let delta = max - min;

    let s = if 0.0 == max { 0.0 } else { delta / max };
    let h = if max == min {
        0.0
    } else {
        hue_degrees(c, max, delta)
    };

    Hsv::new(h, s, v)
}

/// `ColorConverter::rgbToCMYK`.
pub fn rgb_to_cmyk(c: &Rgb) -> Cmyk {
    let (max, _) = extremes(c);
    let k = 1.0 - max;

    // Pure black: the ink ratios would be 0/0, so they are defined as zero.
    // The test is on `k` rather than on `max`, which also catches inputs small
    // enough that `1.0 - max` rounds back to exactly 1.0.
    if k == 1.0 {
        return Cmyk::new(0.0, 0.0, 0.0, 1.0);
    }

    Cmyk::new(
        ((1.0 - c.r) - k) / (1.0 - k),
        ((1.0 - c.g) - k) / (1.0 - k),
        ((1.0 - c.b) - k) / (1.0 - k),
        k,
    )
}

/// `ColorConverter::rgbToYUV`, using the BT.601 coefficients.
pub fn rgb_to_yuv(c: &Rgb) -> Yuv {
    let (r, g, b) = (c.r, c.g, c.b);
    Yuv::new(
        0.299 * r + 0.587 * g + 0.114 * b,
        -0.147 * r - 0.289 * g + 0.436 * b,
        0.615 * r - 0.515 * g - 0.100 * b,
    )
}
